#include <iostream>
#include <vector>
using namespace std;
int decode(int b) {
    int h[4] = {0x55, 0x66, 0x78, 0xFF};
    int s = 0;
    for(int i=0; i<4; i++) {
        int cnt = 0;
        for(int j=0; j<8; j++) if((h[i]>>j&1) && (b>>j&1)) cnt++;
        if(cnt%2) s |= (1<<i);
    }
    if((s&7) != 0) {
        if((s>>3)&1) b ^= (1<<(s&7)); else return -1;
    }
    return (b>>3&1) | (b>>4&2) | (b>>5&4) | (b>>6&8);
}
int main() {
    int n; cin >> n; if(n%2) { cout << "Mesajul este corupt!"; return 0; }
    string res = "";
    for(int i=0; i<n; i+=2) {
        int b1, b2; cin >> b1 >> b2;
        int v1 = decode(b1), v2 = decode(b2);
        if(v1 == -1 || v2 == -1) { cout << "Mesajul este corupt!"; return 0; }
        res += (char)(v1 | (v2 << 4));
    }
    cout << res; return 0;
}

