void v_dec(string &s, vector<int> k) {
    for(int i=0; i<s.length(); i++) s[i] = (s[i]-'A' - k[i%k.size()] + 26)%26 + 'A';
}
int main() {
    string art = "UNPUGNTHFKSEJTYWRRLCIHMGXW", pref = "ACADNET";
    vector<int> k1(7), k2(4);
