    string enc; cin >> enc;
    for(int i=0; i<4; i++) k2[i] = (enc[i]-'A' - (pref[i]-'A') - k1[i%7] + 52) % 26;
    v_dec(enc, k2); v_dec(enc, k1);
    cout << enc; return 0;
}

#include <map>
#include <iostream>
template<typename K, typename V>
class interval_map {
    V m_valBegin;
public:
    std::map<K,V> m_map;
    interval_map(V const& val): m_valBegin(val) {}
    void assign(K const& keyBegin, K const& keyEnd, V const& val) {
        if (!(keyBegin < keyEnd)) return;
        auto itEnd = m_map.lower_bound(keyEnd);
        V valAfter = (itEnd == m_map.begin()) ? m_valBegin : std::prev(itEnd)->second;
        auto itBegin = m_map.lower_bound(keyBegin);
        if (itBegin != itEnd) m_map.erase(itBegin, itEnd);
        V valBefore = (m_map.lower_bound(keyBegin) == m_map.begin()) ? m_valBegin : std::prev(m_map.lower_bound(keyBegin))->second;
        if (!(val == valBefore)) m_map.insert_or_assign(keyBegin, val);
        if (!(valAfter == val)) m_map.insert_or_assign(keyEnd, valAfter);
    }
};

